            } else {
              parentBlocks.add(block);
            }
          }
        }
        for (final block in toolResults) {
          records.add(
            ForeignMessage(
              lineNumber: number,
              role: 'toolResult',
              contents: parseForeignContent(
                block['content'],
                () => skippedBlocks++,
              ),
              rawMessage: block,
              toolCallId: block['tool_use_id'] as String?,
            ),
          );
        }
