        continue;
      }
      // Unmodeled types (`last-prompt`, `permission-mode`, hook
      // attachments, ...) ride as inert custom data (GOAL C2).
      records.add(
        ForeignUnhandled(
          lineNumber: number,
          type: json['type'] as String? ?? 'unknown',
          raw: json,
        ),
      );
    }
