  // flow ranged prefix reads already give (GOAL E11 reporting parity).
  if (size <= limits.maxFileBytes) continue;
} else if (!headerCwdMatches(header.cwd, cwd)) {
  continue;
}
```
But the summary needs sourceId — currently `sourceId: header.id`. When header == null (over-cap), use the file stem fallback:

```dart
final stem = path.split('/').last;
...
sourceId: header?.id ?? (stem.endsWith('.jsonl') ? stem.substring(0, stem.length - '.jsonl'.length) : stem),
headerCwd: header?.cwd ?? '',
title: header?.title ?? '',
