    : _fs = LocalFileSystem(cwd: cwd),
      _shell =
          shell ??
          (diskFreeProbe == null
              ? const LocalShell()
              : LocalShell(diskFreeProbe: diskFreeProbe));

  /// Low-disk probe for background-job logs (issue #919); null = default
  /// `df`-based probe.
  final Future<int?> Function(String directory)? diskFreeProbe;

