+  final io = _TerminalCliIO(headless: true);
+  final env = LocalExecutionEnv(cwd: args.cwd ?? Directory.current.path);
+  final sessionRoot = args.sessionRoot ?? _defaultSessionRoot();
+  final home = _homeDir();
