+      '(expected store: ${expectedStoreRoot(command.harness, home)})',
+    );
+    return 2;
+  }
+  final result = await runImport(
+    adapter: adapter,
+    fs: env,
+    repo: repo,
+    cwd: env.cwd,
+    selector: command.all
+        ? const ImportSelector.all()
+        : ImportSelector.one(command.session!),
+    limits: const ImportLimits(),
