          ForeignMessage(
            lineNumber: number,
            role: message['role'] as String? ?? json['type'] as String? ?? '',
            contents: parseForeignContent(
              rawContent is List ? parentBlocks : rawContent,
              () => skippedBlocks++,
            ),
            rawMessage: message,
