      // attachments, ...) ride as inert custom data (GOAL C2).
      records.add(
        ForeignUnhandled(
          lineNumber: number,
          type: json['type'] as String? ?? 'unknown',
          raw: json,
        ),
      );
    }
    return ForeignParseResult(
      records: records,
      skippedRecords: skipped,
      skippedBlocks: skippedBlocks,
    );
  }

