      final json = decodeJsonLine(line.text!);
      if (json == null) continue;
      final isPhysical = line.number == headerLine ||
          (line.number == 1 && json['type'] == 'title');
      final id = json['id'];
      if (!isPhysical && !(id is String && branch.pathIds.contains(id))) {
        continue;
