  /// The command exceeded [ShellExecOptions.timeout].
  timeout,

  /// No shell is available in this environment (e.g. web).
  shellUnavailable,

  /// The process could not be spawned.
  spawnError,

  /// An output callback threw.
  callbackError,

  /// Any other failure.
  unknown,
}

