/// Local [ExecutionEnv]: [LocalFileSystem] plus [LocalShell].
///
/// Exported only from `lib/io.dart`.
final class LocalExecutionEnv
    implements
        ExecutionEnv,
        BackgroundShell,
        RangedReadFileSystem,
