/// UT tier for the pure mapper (GOAL M-section): the omp mapping golden
/// (REG-4), toolCall pairing + orphans (AC5), unseen-type tolerance (AC6),
/// claude main-chain vs sidechain (AC8/E13), and the byte-exact
/// customType preservation invariant.
void main() {
  late Directory home;
  late Directory project;
  late LocalExecutionEnv fs;

  String fixture(String name) => File(
    'test/import/fixtures/$name',
  ).readAsStringSync().replaceAll('__CWD__', project.path);

  Future<ForeignParseResult> readOmp(String fixtureName) async {
    final bucket = Directory(
      '${home.path}/.omp/agent/sessions/--${project.path
          .replaceFirst('/', '')
          .replaceAll('/', '-')}--',
    )..createSync(recursive: true);
    File('${bucket.path}/session.jsonl').writeAsStringSync(fixture(fixtureName));
    final adapter = OmpAdapter();
    final summaries = await adapter.discover(
      fs: fs,
      cwd: project.path,
      homeDir: home.path,
      tempDir: Directory.systemTemp.path,
      limits: const ImportLimits(),
    );
    return adapter.read(
      fs: fs,
      summary: summaries.firstWhere((s) => s.sourceId != 'x1'),
      homeDir: home.path,
      limits: const ImportLimits(),
    );
  }

  setUp(() {
    home = Directory.systemTemp.createTempSync('fa_import_map_home');
    project = Directory.systemTemp.createTempSync('fa_import_map_proj');
    fs = LocalExecutionEnv(cwd: project.path);
  });

  tearDown(() {
    home.deleteSync(recursive: true);
    project.deleteSync(recursive: true);
  });

  test('REG-4: the omp fixture maps to the pinned record sequence', () async {
    final mapped = mapForeignSession(await readOmp('omp_modern.jsonl'), 'omp');
====
    final compaction = mapped.items
        .map((i) => i.planned)
        .whereType<PlannedCompaction>()
        .single;
    expect(
      compaction.summary,
      'The conversation so far fixed the login flow',
    );
    expect(mapped.droppedFields['shortSummary'], 1);
    expect(mapped.droppedFields['firstKeptEntryId'], 1);
    expect(mapped.droppedFields['tokensBefore'], 1);
  });

  test('non-conversation roles map to inert customs, never messages', () async {
    final mapped = mapForeignSession(await readOmp('omp_modern.jsonl'), 'omp');
    final bash = mapped.items
        .map((i) => i.planned)
        .whereType<PlannedCustom>()
        .firstWhere((c) => c.customType == 'import.omp.bashExecution');
    expect((bash.data as Map)['role'], 'bashExecution');
  });

  test('claude: main chain imports, sidechain excluded and counted '
      '(AC8/E13)', () async {
    final bucket = Directory(
      '${home.path}/.claude/projects/${claudeProjectSlug(project.path)}',
    )..createSync(recursive: true);
    File('${bucket.path}/claude-0001.jsonl')
        .writeAsStringSync(fixture('claude_basic.jsonl'));
    final adapter = ClaudeAdapter();
    final summaries = await adapter.discover(
      fs: fs,
      cwd: project.path,
      homeDir: home.path,
      tempDir: Directory.systemTemp.path,
      limits: const ImportLimits(),
    );
    expect(summaries, hasLength(1));
    final parse = await adapter.read(
      fs: fs,
      summary: summaries.single,
      homeDir: home.path,
      limits: const ImportLimits(),
    );
    final mapped = mapForeignSession(parse, 'claude');

    // The sidechain and the off-branch fork never reach the plans.
    final plannedText = mapped.items
        .map((i) => i.planned)
        .map((p) => switch (p) {
              PlannedCustom(:final data) => data.toString(),
              PlannedMessage(:final message) => message.toJson().toString(),
              _ => '',
            })
        .join('\n');
    expect(plannedText, isNot(contains('sidechain thing')));
    expect(plannedText, isNot(contains('off-branch fork answer')));
    // Sidechain (u3) + off-branch fork (a2) counted skipped.
    expect(parse.skippedRecords, greaterThanOrEqualTo(2));

    // last-prompt / permission-mode ride as inert claude customs.
    final customs = mapped.items
        .map((i) => i.planned)
        .whereType<PlannedCustom>()
        .toList();
    final customTypes = customs.map((c) => c.customType).toSet();
    // AC6/M-invariant: every unmapped type lands namespaced as
    // import.<harness>.<type>, never a bare import.claude line.
    expect(customTypes, containsAll([
      'import.claude.session',
      'import.claude.last-prompt',
      'import.claude.permission-mode',
    ]));
    expect(customTypes.contains('import.claude'), isFalse);
    final inertTypes = customs
        .map((c) => c.data is Map ? (c.data as Map)['type'] : null)
        .toSet();
    expect(inertTypes, containsAll(['last-prompt', 'permission-mode']));

    // tool_use → toolCall; the lifted tool_result pairs with it (AC5).
    final call = mapped.items
        .map((i) => i.planned)
        .whereType<PlannedMessage>()
        .map((p) => p.message)
        .whereType<AssistantMessage>()
        .expand((m) => m.content)
        .whereType<ToolCall>()
        .single;
    expect(call.id, 'tu-1');
    final result = mapped.items
        .map((i) => i.planned)
        .whereType<PlannedMessage>()
        .map((p) => p.message)
        .whereType<ToolResultMessage>()
        .single;
    expect(result.toolCallId, 'tu-1');

    // Main chain in parentUuid order: u1 → a1 → (lifted result + u2) → u4.
    final ordered = [
      for (final item in mapped.items)
        if (item.planned is PlannedMessage)
          (item.planned as PlannedMessage).message.role,
    ];
    expect(ordered, ['user', 'assistant', 'toolResult', 'user', 'user']);
  });
}

AGENTS.md is a huge project journal, not a style guide per se. The relevant conventions I already see in the code: capability-stripping wrappers in tests (`_NoRenameEnv`), Result-based fs API, `// comment` style with GOAL references.

Now, TDD RED — write the test first. I'll add a focused test file `test/import/claude_adapter_test.dart`? Hmm — or add to existing files? There's no claude_adapter_test.dart; claude coverage lives in import_mapper_test.dart. But a discovery-tier test (non-ranged backend) fits the omp_adapter_test.dart UT-tier shape. Options:

- Create `test/import/claude_adapter_test.dart` with the non-ranged oversize tests for claude (and maybe move nothing — just new tests).
- Add omp mirror test to `test/import/omp_adapter_test.dart`.

That's clean: one new UT file for the claude discovery parity + one added test in the omp UT file for the omp mirror. Both need the non-ranged wrapper — duplicating a tiny wrapper in two files is meh; but a shared helper would need a new file... The repo's test style has local helpers per file (each test file defines its own writeBucket etc.). I'll define the small `_NoRangeEnv` wrapper in the new claude test file, and for the omp mirror... hmm.

Actually — wait. Let me reconsider whether touch the omp adapter at all.

Arguments FOR mirroring in omp:
- The thread's core demand is reporting parity: an oversized file must never vanish silently.
- If I fix only claude, the non-ranged asymmetry flips: claude warns, omp vanishes. The next review round would flag omp (same pattern across codebase rule).
- The author's own stated principle: "Both adapters therefore match per-path."

Arguments AGAINST:
- Scope discipline: the flagged file is claude_adapter.dart.
- omp's ranged path already has the desired behavior; only non-ranged vanishes.

The formatting_rules F3 says: "Be surgical but thorough — fix exact issues flagged, then check same pattern across codebase". The same pattern DOES exist in omp. I'll mirror — it's a small, symmetric change that makes the invariant uniform: an oversized file NEVER vanishes at discovery; it becomes a summary and refuses at read time with the counted warning, on every backend, for both adapters.

Design detail for omp: when header == null and over cap → include summary with sourceId = file stem, headerCwd = ''. For ranged backends, the header read succeeds (uncapped prefix) → real id/cwd → current behavior preserved byte-for-byte.

Design detail for claude: when headerCwd == '' (non-ranged gate or genuinely no cwd) and size > cap → include with headerCwd ''. For ranged, _firstCwd reads the real cwd → current behavior preserved.

Wait — one more consideration for claude ranged + over-cap: `_firstCwd` ranged branch reads 4096 bytes and finds the cwd → headerCwd non-empty → `headerCwdMatches` decides. If the cwd matches → included (current). Unchanged. ✓

And claude non-ranged, file NOT over cap, but no cwd in first lines → headerCwd '' → size <= cap → skip (current). ✓

