  'an over-cap file on a non-ranged backend is still discovered and '
  'refuses at read time with the counted warning (E11 reporting parity)',
  () async {
    final bucket = ... claude bucket ...;
    File('${bucket.path}/big.jsonl').writeAsStringSync(claudeFixture);
    final noRange = _NoRangeEnv(fs);
    final adapter = ClaudeAdapter();
    final summaries = await adapter.discover(
      fs: noRange, cwd: project.path, homeDir: home.path,
      tempDir: Directory.systemTemp.path,
      limits: const ImportLimits(maxFileBytes: 8),
    );
    // Discovered — not vanished (review round 5, thread 26).
    expect(summaries, hasLength(1));
    // The read-time refusal carries the size reason; runImport renders
    // it as `warning: skipped <id>: file too large ...`.
    await expectLater(
      adapter.read(fs: noRange, summary: summaries.single, homeDir: home.path, limits: const ImportLimits(maxFileBytes: 8)),
      throwsA(isA<ForeignFileError>().having((e) => e.message, 'message', contains('file too large'))),
    );
  },
